#' Item-Restscore Correlations
#'
#' Computes observed and model-expected item-restscore correlations using
#' Goodman-Kruskal's gamma, via the easyRasch2 R package
#' (iarm::item_restscore() on a conditional maximum likelihood fit from
#' psychotools, with WLE person estimates for the relative item
#' locations). Reports observed vs. expected restscore correlations, the
#' signed difference (observed minus expected; positive =
#' over-discrimination / often LD, negative = under-discrimination /
#' often noise), BH-adjusted p-values, and item locations. The
#' asymptotic p-values are miscalibrated under the Rasch model;
#' simulation-based cutoffs replace them with parametric bootstrap
#' p-values from easyRasch2::RMitemRestscoreCutoff(). Results match
#' easyRasch2::RMitemRestscore().
#' 
#' @param data .
#' @param vars .
#' @param computeCutoff .
#' @param hdciWidth .
#' @param iterations .
#' @param seed .
#' @param pValues .
#' @param correction .
#' @param sortByDiff .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$restscoreTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$restscoreNote} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$restscorePlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$restscoreTable$asDF}
#'
#' \code{as.data.frame(results$restscoreTable)}
#'
#' @export
itemrestscore <- function(
    data,
    vars,
    computeCutoff = FALSE,
    hdciWidth = 95,
    iterations = 400,
    seed = 42,
    pValues = TRUE,
    correction = "fwer",
    sortByDiff = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("itemrestscore requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- itemrestscoreOptions$new(
        vars = vars,
        computeCutoff = computeCutoff,
        hdciWidth = hdciWidth,
        iterations = iterations,
        seed = seed,
        pValues = pValues,
        correction = correction,
        sortByDiff = sortByDiff)

    analysis <- itemrestscoreClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

